package com.example.g.activities;
import android.os.*;import android.widget.TextView;import androidx.activity.result.*;import androidx.activity.result.contract.ActivityResultContracts;import androidx.appcompat.app.AppCompatActivity;import com.example.g.R;import com.example.g.core.permissions.PermissionManager;import com.google.android.material.button.MaterialButton;import com.google.android.material.dialog.MaterialAlertDialogBuilder;
public class OnboardingActivity extends AppCompatActivity{int step=0;TextView title,message;MaterialButton primary,secondary;ActivityResultLauncher<String[]> permissions=registerForActivityResult(new ActivityResultContracts.RequestMultiplePermissions(),r->showDelete());@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_onboarding);((android.widget.ImageView)findViewById(R.id.app_logo)).setImageDrawable(com.example.g.ui.AppLogoManager.drawable(this));title=findViewById(R.id.title);message=findViewById(R.id.message);primary=findViewById(R.id.primary);secondary=findViewById(R.id.secondary);primary.setOnClickListener(v->{if(step==0)showPermissions();else if(step==1)requestPermissions();else finishSetup();});}void showPermissions(){step=1;title.setText("Media access");message.setText(R.string.permission_explanation);primary.setText(R.string.grant_access);}void requestPermissions(){PermissionManager.markMediaPermissionRequested(this);permissions.launch(PermissionManager.mediaPermissions());}void showDelete(){step=2;title.setText("Protect deletion");message.setText("Choose how Luma confirms destructive actions. You can change this later in Security settings.");primary.setText("Choose protection");primary.setOnClickListener(v->new MaterialAlertDialogBuilder(this).setTitle("Delete protection").setSingleChoiceItems(new String[]{"Biometric","PIN","Biometric with PIN fallback - Recommended","Simple confirmation"},2,(d,w)->{getSharedPreferences("settings",0).edit().putInt("delete_mode",w).apply();d.dismiss();showVault();}).show());}void showVault(){step=3;title.setText("Private Vault");message.setText("Vault items are encrypted with AES-GCM and kept in app-private storage. You can enable it later.");primary.setText("Continue");primary.setOnClickListener(v->finishSetup());}void finishSetup(){getSharedPreferences("settings",0).edit().putBoolean("setup_complete",true).apply();startActivity(new android.content.Intent(this,MainActivity.class));finish();}}
